import{_ as t,o as i,c as s,j as e,a as r}from"./chunks/framework.QCr1ZR1X.js";const c=JSON.parse('{"title":"思维导图-第8章-工业互联网核心技术","description":"","frontmatter":{},"headers":[],"relativePath":"mindmap/思维导图-第8章-工业互联网核心技术.md","filePath":"mindmap/思维导图-第8章-工业互联网核心技术.md","lastUpdated":1786967935000}'),o={name:"mindmap/思维导图-第8章-工业互联网核心技术.md"};function n(d,a,_,m,A,l){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"思维导图-第8章-工业互联网核心技术",tabindex:"-1"},[r("思维导图-第8章-工业互联网核心技术 "),e("a",{class:"header-anchor",href:"#思维导图-第8章-工业互联网核心技术","aria-label":'Permalink to "思维导图-第8章-工业互联网核心技术"'},"​")],-1),e("div",{class:"mermaid"},'# 第8章 工业互联网核心技术 — 思维导图 ## 8.1 5G与工业互联网 ### 5G三大模式 - eMBB（增强移动宽带） - 峰值10Gbps - 适合：高清视频巡检/AR远程协作 - uRLLC（超可靠低时延通信） - 延迟<1ms，可靠性99.9999% - 适合：远程操控龙门吊/AGV协同调度 - mMTC（大规模机器类型通信） - 100万连接/km² - 适合：数万传感器统一接入 ### 5G RedCap（轻量化5G） - 3GPP R17标准 - 填补eMBB和mMTC之间的中等速率、低功耗空白 - 2024年起规模商用 ### 5G专网三种部署模式 - 独立专网：基站+核心网全自建，安全性最高 - 混合专网：共享基站/独享核心网用户面 - 虚拟专网：网络切片，成本最低但隔离性有限 ### 5G云化PLC - PLC逻辑从车间物理盒子迁移到云端/边缘服务器 - 通过5G uRLLC+专网远程控制 - 安全关键逻辑（急停、安全联锁）必须由本地硬件安全PLC执行 - 鞍钢案例 - 鞍山本部 ↔ 150公里外鲅鱼圈厂区 - 远程控制中包翻包机 - 4.9GHz+2.6GHz双频主备链路毫秒级热备切换 - 节省至少10名操作人员 - 芜湖美的案例 - 5G-A+云化PLC - 端到端延迟<10ms，可靠性99.999% - 工信部第六届"绽放杯"全国总决赛一等奖 ## 8.2 人工智能与工业应用 ### 工业AI三种主要形态 - 视觉检测 - 电路板焊点/元件缺陷检测 - 不疲劳，标准一致 - 预测性维护 - 从振动频谱识别早期故障特征 - 实现"没坏先修" - 工艺优化 - 在成千上万参数组合中搜索最优方案 ### 工业视角：AI不能做什么 - 不能替代硬件安全PLC/安全继电器执行紧急安全功能 - 存在可解释性问题（深度模型无法解释"为什么"） - 数据依赖（新设备无历史数据则AI无经验） - AI是辅助工具，不是决策者 ## 8.3 数字孪生：物理工厂的"数字兄弟" ### 数字孪生的起源 - Michael Grieves教授2002年提出"镜像空间模型" - NASA 2010年正式使用"Digital Twin"术语 ### 数字孪生与仿真的区别 - 仿真：离线（输入参数→运行一次→得到结果→停止） - 数字孪生：在线（物理世界持续驱动数字模型，可反向控制） ### 三个递进的层次 - 以虚映实：物理状态镜像到数字空间 - 以虚控实：数字空间指令反向控制物理设备 - 以虚优实：数字空间低成本试错找到最优方案再应用于物理世界 ## 8.4 区块链与工业可信互联 ### 联盟链 - 参与方需授权才能加入 - 共识效率远高于公链 ### 应用场景与落地现状 - 供应链追溯 - 设备身份认证 - 目前实际落地案例较少，仍处早期探索阶段 ## 8.5 工业安全：永远的底线 ### 纵深防御五原则 - 物理隔离 - 访问控制 - 数据加密 - 安全审计 - 应急响应 ## 8.6 动手实践：AI辅助编程入门 ### 四种AI编程工具形态 - 网页对话式：ChatGPT/DeepSeek等 - APP交互式：手机端快速查询 - AI专用IDE：Cursor/Windsurf（可读取整个项目上下文） - 通用IDE插件：GitHub Copilot/通义千问/Continue ### 实践任务 - 用AI生成温度监控JavaScript代码 - 用AI生成完整MQTT数据采集发布代码 - Node.js - 模拟传感器 → MQTT → JSON格式 - 用AI生成MQTT数据存储代码 - 订阅 → CSV文件按日期保存 - 讨论：AI写代码，谁为后果负责？ ## 全书回顾：从一根网线到一座数字工厂 ### 全书技术全景图 - 现场设备 → Modbus等 → 边缘网关 → MQTT → 工业互联网平台 → 工业APP → 管理者/操作员 ## 🎯 课程思政 - AI的边界，人的责任——工业智能中的伦理抉择 - AI是工具不是决策者 - 安全关键场景中必须由人做最终决策 - 参考：IEEE 7000系列、欧盟AI Act、中国《新一代人工智能治理原则》 - 安全是永远的底线——工业互联网从业者的责任担当 - 震网病毒事件（2010年）：首个造成物理破坏的网络武器，约1000台离心机损毁 - Colonial Pipeline事件（2021年）：勒索软件导致东海岸燃油中断6天，17个州进入紧急状态 - 工业安全不是"IT问题"而是"国家安全问题"',-1)])])}const I=t(o,[["render",n]]);export{c as __pageData,I as default};
